-- StockSync generated SQL export
-- Generated from synthetic CSV data

PRAGMA foreign_keys = ON;

CREATE TABLE "products" ("product_id" TEXT PRIMARY KEY, "product_name" TEXT, "category" TEXT, "brand" TEXT, "unit_cost" TEXT, "unit_price" TEXT, "is_active" TEXT, "created_at" TEXT);

-- Records for products

CREATE TABLE "skus" ("sku_id" TEXT PRIMARY KEY, "product_id" TEXT, "sku_code" TEXT, "sku_name" TEXT, "barcode" TEXT, "unit_of_measure" TEXT, "weight_kg" TEXT, "is_active" TEXT, "created_at" TEXT, "unit_price" TEXT);

-- Records for skus

CREATE TABLE "locations" ("location_id" TEXT PRIMARY KEY, "location_name" TEXT, "location_type" TEXT, "city" TEXT, "state" TEXT, "country" TEXT, "is_active" TEXT, "created_at" TEXT);

-- Records for locations

CREATE TABLE "inventory_balances" ("balance_id" TEXT PRIMARY KEY, "sku_id" TEXT, "location_id" TEXT, "on_hand" TEXT, "reserved" TEXT, "blocked" TEXT, "safety_stock" TEXT, "in_transit" TEXT, "available_stock" TEXT, "last_updated" TEXT);

-- Records for inventory_balances

CREATE TABLE "inventory_movements" ("movement_id" TEXT PRIMARY KEY, "sku_id" TEXT, "location_id" TEXT, "movement_type" TEXT, "quantity" TEXT, "reference_id" TEXT, "reason" TEXT, "created_at" TEXT);

-- Records for inventory_movements

CREATE TABLE "orders" ("order_id" TEXT PRIMARY KEY, "customer_id" TEXT, "channel" TEXT, "order_status" TEXT, "fulfillment_location_id" TEXT, "order_total" TEXT, "created_at" TEXT, "updated_at" TEXT);

-- Records for orders

CREATE TABLE "order_lines" ("order_line_id" TEXT PRIMARY KEY, "order_id" TEXT, "sku_id" TEXT, "quantity" TEXT, "unit_price" TEXT, "line_total" TEXT);

-- Records for order_lines

CREATE TABLE "reservations" ("reservation_id" TEXT PRIMARY KEY, "order_id" TEXT, "sku_id" TEXT, "location_id" TEXT, "quantity" TEXT, "reservation_status" TEXT, "reserved_at" TEXT, "expires_at" TEXT, "released_at" TEXT);

-- Records for reservations

CREATE TABLE "replenishment_rules" ("rule_id" TEXT PRIMARY KEY, "sku_id" TEXT, "location_id" TEXT, "reorder_point" TEXT, "reorder_quantity" TEXT, "lead_time_days" TEXT, "safety_stock" TEXT, "is_active" TEXT);

-- Records for replenishment_rules

CREATE TABLE "anomaly_scenarios" ("scenario_id" TEXT PRIMARY KEY, "anomaly_type" TEXT, "entity_type" TEXT, "entity_id" TEXT, "field_name" TEXT, "baseline_value" TEXT, "anomalous_value" TEXT, "description" TEXT, "evidence" TEXT);

-- Records for anomaly_scenarios

CREATE TABLE "ground_truth" ("scenario_id" TEXT PRIMARY KEY, "entity_type" TEXT, "entity_id" TEXT, "label" TEXT, "anomaly_type" TEXT);

